insert into public.signals (id, kind, title, description, state, lat, lon, radius_km, highways, starts_at, ends_at, severity, transit_multiplier, source, provenance) values
  ('sig-rain-veracruz', 'weather', 'Heavy rain and landslide risk, central Veracruz', 'Late rainy season: saturated slopes on the Orizaba–Puebla stretch of MEX-150D. Trucks queue at partial closures and transit from Orizaba stretches from 2 to about 5 days.', 'Veracruz', 18.85, -97.1, 90, ARRAY['MEX-150D']::text[], '2026-09-28', '2026-10-20', 'high', 2.6, 'SMN/CONAGUA seasonal outlook (seeded for demo)', 'estimated'),
  ('sig-hurricane-gulf', 'weather', 'Hurricane watch, Gulf of Mexico coast', 'A tropical system is forecast to approach the Veracruz coast; heavy rain inland on 8–12 Oct. A watch, not a warning.', 'Veracruz', 19.2, -96.13, 120, '{}'::text[], '2026-10-08', '2026-10-12', 'medium', 1.3, 'SMN tropical cyclone bulletin (seeded for demo)', 'estimated'),
  ('sig-closure-57d', 'road', 'Road closure, MEX-57D near Palmillas', 'Lane closure for bridge repair; trucks are diverted for a few hours at a time.', 'Querétaro', 20.37, -99.95, 25, ARRAY['MEX-57D']::text[], '2026-10-03', '2026-10-08', 'medium', 1.3, 'Capufe / SCT road report (seeded for demo)', 'estimated'),
  ('sig-blockade-puebla', 'blockade', 'Highway blockade, Puebla–Tlaxcala corridor', 'Community blockade on MEX-119 and MEX-190 near Amozoc. Cargo is held or rerouted through side roads.', 'Puebla', 19.05, -98.05, 60, ARRAY['MEX-119','MEX-190']::text[], '2026-10-04', '2026-10-09', 'medium', 1.7, 'Local news and carrier reports (seeded for demo)', 'estimated'),
  ('sig-theft-45d57d', 'theft', 'Cargo theft hotspot, MEX-45D / MEX-57D at night', 'Reported hijackings on the Celaya–Querétaro and Querétaro–San Luis Potosí stretches between 20:00 and 05:00. Carriers add escorts or hold trucks until daylight.', 'Guanajuato', 20.5, -100.6, 70, ARRAY['MEX-45D','MEX-57D']::text[], '2026-09-20', '2026-11-15', 'medium', 1.06, 'Carrier incident reports (seeded for demo)', 'estimated'),
  ('sig-port-manzanillo', 'port', 'Container congestion, Port of Manzanillo', 'Yard saturation and customs queues delay container release by 3–5 days; imported resin reaches the supplier late and outbound loads slip.', 'Colima', 19.05, -104.32, 80, ARRAY['MEX-200']::text[], '2026-09-25', '2026-10-18', 'medium', 1.5, 'API Manzanillo terminal notice (seeded for demo)', 'estimated'),
  ('sig-press-edl', 'supplier', 'Press 4 breakdown, Estampados del Laja', 'Die change overran on Press 4 (400 t). Output is being recovered with overtime; outbound shipments leave later in the day, and more of them at night.', 'Guanajuato', 20.52, -100.81, 5, '{}'::text[], '2026-10-04', '2026-10-12', 'medium', 1.3, 'Supplier-reported through FlowTwin (seeded for demo)', 'estimated'),
  ('sig-rain-toluca', 'weather', 'Heavy afternoon rain, Toluca valley', 'Daily storms flood low-lying roads around Toluca and slow trucks on MEX-15D.', 'México', 19.29, -99.65, 50, '{}'::text[], '2026-09-30', '2026-10-15', 'low', 1.1, 'SMN daily forecast (seeded for demo)', 'estimated');
