insert into public.alerts (id, customer_id, supplier_id, part_ids, signal_id, level, title, message, created_at, expected_shortfall_date, line_stop_exposure_eur, status, actions, chosen_action_id, supplier_response) values
  ('alert-hmo-qss', 'qss', 'hmo', ARRAY['part-qss-6120-lmb']::text[], 'sig-rain-veracruz', 'red', 'Transit from Orizaba goes from 2 to 5 days', 'QRO Seating Systems holds 3 days of cover of lumbar air line, 6 mm hose assembly (QSS-6120-LMB). With transit at 5 days (up to 8.3 in the worst case) and nothing done, cover runs out in about 2 days, around 7 Oct 2026.', '2026-10-05', '2026-10-07', 6848000, 'new', '[{"id": "act-hmo-1", "label": "Pull the next order forward", "description": "Ask Hules y Mangueras de Orizaba to ship the next two orders before the rain peaks, adding about 1.5 days of cover."}, {"id": "act-hmo-2", "label": "Add 2 days of safety stock", "description": "Raise the lumbar air line safety stock to 5 days until the rainy season ends (about MX$38k of inventory)."}, {"id": "act-hmo-3", "label": "Use the alternative route via Tehuacán", "description": "Route trucks through Tehuacán and Cuacnopalan (MEX-150 free road) to avoid the landslide-prone Orizaba–Puebla toll stretch."}]'::jsonb, DEFAULT, DEFAULT),
  ('alert-pip-qss', 'qss', 'pip', ARRAY['part-qss-7205-trm']::text[], 'sig-blockade-puebla', 'amber', 'Highway blockade, Puebla–Tlaxcala corridor', 'QRO Seating Systems holds 1.5 days of cover of seat side trim cover (QSS-7205-TRM). Transit is 1.1 days against 1 planned (up to 2.8 in the worst case). Without action, projected cover falls to 0.2 days around 6 Oct 2026; no stop is expected in the next 14 days, but a bad week could stop the line.', '2026-10-03', DEFAULT, 862000, 'acknowledged', '[{"id": "act-pip-1", "label": "Pull the next order forward", "description": "Ask Plásticos Inyectados de Puebla to ship one day early, before the blockade peaks."}, {"id": "act-pip-2", "label": "Use the alternative route via MEX-150D", "description": "Reroute through MEX-150D toll road, bypassing the Amozoc–Tlaxcala corridor."}, {"id": "act-pip-3", "label": "Add 2 days of safety stock", "description": "Build 2 days of cover on the seat side trim cover; it is single-source and a line-stopper."}]'::jsonb, 'act-pip-1', DEFAULT),
  ('alert-tsr-qss', 'qss', 'tsr', ARRAY['part-qss-9011-fls']::text[], 'sig-closure-57d', 'amber', 'Road closure, MEX-57D near Palmillas', 'QRO Seating Systems holds 1.5 days of cover of m6 flange screw, zinc-nickel (QSS-9011-FLS). Transit is 2.1 days against 2 planned (up to 3.5 in the worst case). Without action, projected cover falls to 0.7 days around 5 Oct 2026; no stop is expected in the next 14 days, but a bad week could stop the line.', '2026-10-04', DEFAULT, 283000, 'new', '[{"id": "act-tsr-1", "label": "Pull the next order forward", "description": "Ask Tornillos y Sujetadores to ship Thursday''s flange screw order on Tuesday."}, {"id": "act-tsr-2", "label": "Add 3 days of safety stock", "description": "Buy a one-off buffer of M6 flange screws; at MX$0.62 each this is under MX$30k for 3 days."}, {"id": "act-tsr-3", "label": "Qualify the second source", "description": "Flange screws are single-source. Qualify a second heading shop in the Bajío."}]'::jsonb, DEFAULT, DEFAULT),
  ('alert-rdp-qss', 'qss', 'rdp', ARRAY['part-qss-5310-pab']::text[], 'sig-port-manzanillo', 'amber', 'Transit from Manzanillo goes from 2 to 3 days', 'QRO Seating Systems holds 2 days of cover of pa6 glass-filled resin, seat base compound (QSS-5310-PAB). Transit is 3 days against 2 planned (up to 3.8 in the worst case). Without action, projected cover falls to 1 days around 5 Oct 2026; no stop is expected in the next 14 days, but a bad week could stop the line.', '2026-10-02', DEFAULT, 147000, 'new', '[{"id": "act-rdp-1", "label": "Ask for resin on hand", "description": "Ask Resinas del Pacífico to confirm how many days of PA6 compound it has outside the port."}, {"id": "act-rdp-2", "label": "Add 3 days of safety stock", "description": "Raise PA6 compound stock at QSS to 6 days while the port clears."}, {"id": "act-rdp-3", "label": "Qualify the second source", "description": "Qualify a domestic PA6 compound source so a port delay does not reach the line."}]'::jsonb, DEFAULT, DEFAULT),
  ('alert-edl-qss', 'qss', 'edl', ARRAY['part-qss-4480-rcp']::text[], 'sig-press-edl', 'amber', 'Press 4 breakdown, Estampados del Laja', 'QRO Seating Systems holds 1.2 days of cover of recliner mounting plate (QSS-4480-RCP). Transit is 1.4 days against 1 planned (up to 1.9 in the worst case). Without action, projected cover falls to 0.8 days around 5 Oct 2026; no stop is expected in the next 14 days, but a bad week could stop the line.', '2026-10-04', DEFAULT, 76000, 'supplier-responded', '[{"id": "act-edl-1", "label": "Ask for a confirmed ship plan", "description": "Ask Estampados del Laja for a daily ship plan until Press 4 is stable."}, {"id": "act-edl-2", "label": "Move departures to daytime", "description": "Agree that loads for QSS leave between 06:00 and 18:00 to avoid the MEX-45D night theft risk."}, {"id": "act-edl-3", "label": "Add 2 days of safety stock", "description": "Hold 2 extra days of the recliner mounting plate while Press 4 recovers."}]'::jsonb, DEFAULT, '{"by": "Roberto Laja", "at": "2026-10-05", "message": "Press 4 is back in production since Monday night. We confirm capacity for the next two QSS orders and will add a Saturday shift if the +15% arrives. Departures for QSS will leave before 18:00.", "confirmedCapacity": true}'::jsonb);
